  | j + 1 => {p | p ∈ Box R ∧ 32 ≤ rho p ∧ ((∃ p' ∈ nb R p, Cj (j + 1) p' < 1) → nb R p ⊆ Fseq R j) ∧
      ((∃ p' ∈ nb R p, 0 < Cj (j + 1) p') → ∀ p' ∈ nb R p, hsP (ordA (j + 1)).1 (ordA (j + 1)).2 p')}

theorem Fseq_box (R j : ℕ) : Fseq R j ⊆ Box R

